layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > .87){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 1.; vP = position.xy*S; vU = u; vK = aK;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }

layers.fragment:
uniform vec3 uV, uBl, uW; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float r = length(vP), a = atan(vP.y, vP.x), t = vU/.87;
      float k = vK < .5 ? pow(clamp(vU/.4, 0., 1.), 2.) : 1. - pow(1. - clamp(vU/.4, 0., 1.), 3.);
      float R = vK < .5 ? mix(.8, .25, k) : mix(.25, .8, k);                  // origin closes, destination opens
      float f = mix(1.7,1.,smoothstep(0.,.07,vU))*(1. - smoothstep(.5, 1., t));
      float ring = exp(-pow(abs(r - R)/.018, 2.4)), inner = exp(-pow(abs(r - R*.72)/.01, 2.4))*.6;
      float ticks = smoothstep(.6, .95, abs(cos(a*12.)))*exp(-pow(abs(r - R*.86)/.03, 2.))*.7;   // sigil ticks between the rings
      float glow = exp(-r*r*6.)*(vU < .1 ? .9 : .25*(1. - t));
      vec3 o = (uV*(ring + inner + ticks) + uBl*glow + uW*lcore(r - R, .005)*.6)*f*smoothstep(1., .9, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
